"""Summarises the graph and runs a few example Cypher queries."""

import logging
from typing import Any, Protocol

logger = logging.getLogger(__name__)

# Schema-agnostic on purpose: the ontology is generated by the LLM, so labels are not known in advance.
EXAMPLE_QUERIES: dict[str, str] = {
    "Most connected entities": (
        "MATCH (n)-[r]-() RETURN labels(n)[0] AS label, n.name AS name, count(r) AS degree "
        "ORDER BY degree DESC LIMIT 5"
    ),
    "Sample facts (subject, relation, object)": (
        "MATCH (a)-[r]->(b) RETURN a.name, type(r), b.name ORDER BY a.name LIMIT 5"
    ),
    "Who or what is linked to the Titanic": (
        "MATCH (a)-[r]-(b) WHERE toLower(a.name) CONTAINS 'titanic' "
        "RETURN a.name, type(r), labels(b)[0], b.name LIMIT 5"
    ),
    "Entities with no relations (extraction quality check)": (
        "MATCH (n) WHERE NOT (n)--() RETURN labels(n)[0] AS label, count(n) AS unlinked ORDER BY unlinked DESC"
    ),
}


class QueryableGraph(Protocol):
    """Anything with FalkorDB's Graph.query interface."""

    def query(self, cypher: str) -> Any:
        """Run a Cypher query and return a result with a result_set attribute."""


def graph_summary(graph: QueryableGraph) -> dict[str, Any]:
    """Return node/edge counts and the count per node label and relationship type."""
    return {
        "nodes": _scalar(graph, "MATCH (n) RETURN count(n)"),
        "edges": _scalar(graph, "MATCH ()-[r]->() RETURN count(r)"),
        "node_labels": _pairs(graph, "MATCH (n) RETURN labels(n)[0] AS label, count(n) AS c ORDER BY c DESC"),
        "relationship_types": _pairs(graph, "MATCH ()-[r]->() RETURN type(r) AS t, count(r) AS c ORDER BY c DESC"),
    }


def log_graph_report(graph: QueryableGraph) -> None:
    """Log the summary followed by each example query and its rows."""
    summary = graph_summary(graph)
    logger.info("Graph summary: %d nodes, %d edges", summary["nodes"], summary["edges"])
    logger.info("Node labels: %s", summary["node_labels"])
    logger.info("Relationship types: %s", summary["relationship_types"])
    for title, cypher in EXAMPLE_QUERIES.items():
        rows = graph.query(cypher).result_set
        logger.info("Example query - %s\n  %s\n%s", title, cypher, "\n".join(f"  -> {row}" for row in rows) or "  (no rows)")


def _scalar(graph: QueryableGraph, cypher: str) -> int:
    """Run a query returning a single number."""
    return graph.query(cypher).result_set[0][0]


def _pairs(graph: QueryableGraph, cypher: str) -> dict[str, int]:
    """Run a query returning (name, count) rows as a dict."""
    return {name: count for name, count in graph.query(cypher).result_set}
